import{_ as p,a0 as o,w as r,s as d,ao as l,I as a,x as e,a1 as s,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在最小安装的 CentOS、RHEL、Rocky Linux 中设置互联网 | LCTT x X-CMD","titleTemplate":false,"description":"如何在最小安装的 CentOS、RHEL、Rocky Linux 中设置互联网 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在最小安装的 CentOS、RHEL、Rocky Linux 中设置互联网 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在最小安装的 CentOS、RHEL、Rocky Linux 中设置互联网 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220926 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install","title":"如何在最小安装的 CentOS、RHEL、Rocky Linux 中设置互联网","tag":"202210","desc":""},"relativePath":"202210/20220926 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install.md","filePath":"[post].md"}'),u={name:"202210/20220926 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install.md"};function g(k,t,h,c,m,b){const i=o("Link");return r(),d("div",null,[t[23]||(t[23]=l('<h1 id="如何在最小安装的-centos、rhel、rocky-linux-中设置互联网" tabindex="-1">如何在最小安装的 CentOS、RHEL、Rocky Linux 中设置互联网 <a class="header-anchor" href="#如何在最小安装的-centos、rhel、rocky-linux-中设置互联网" aria-label="Permalink to “如何在最小安装的 CentOS、RHEL、Rocky Linux 中设置互联网”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/10/162428grhkhtayzt4cdh5k.jpg" alt=""></p><blockquote><p>在最小安装的服务器中设置互联网或网络非常容易。本指南将解释如何在最小安装的 CentOS、RHEL 和 Rocky Linux 中设置互联网或网络。</p></blockquote><p>当你安装了任何服务器发行版的最小安装环境，你将没有任何 GUI 或桌面环境来设置你的网络或互联网。因此，当你只能访问终端时，了解如何设置互联网非常重要。NetworkManager 工具提供了必要的工具，辅以 systemd 服务来完成这项工作。以下是方法。</p><h3 id="在最小安装的-centos、rhel、rocky-linux-中设置互联网" tabindex="-1">在最小安装的 CentOS、RHEL、Rocky Linux 中设置互联网 <a class="header-anchor" href="#在最小安装的-centos、rhel、rocky-linux-中设置互联网" aria-label="Permalink to “在最小安装的 CentOS、RHEL、Rocky Linux 中设置互联网”">​</a></h3><p>在你完成了服务器的安装后，启动进入服务器终端。理想情况下，你会看到一个终端提示符。使用 root 或管理员账户登录。</p>',6)),a("p",null,[t[1]||(t[1]=e("首先，尝试使用 ",-1)),s(i,{href:"https://linux.die.net/man/1/nmcli"},{default:n(()=>[...t[0]||(t[0]=[e("nmcli",-1)])]),_:1}),t[2]||(t[2]=e(" 检查网络接口的状态和详细信息。",-1)),t[3]||(t[3]=a("code",null,"nmcli",-1)),t[4]||(t[4]=e(" 是用于控制 NetworkManager 服务的命令行工具。使用以下命令进行检查。",-1))]),t[24]||(t[24]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmcli device status</span></span></code></pre></div><p>这将显示设备名称、状态等。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/nmcli-device-status.jpg" alt="nmcli device status"></p><p>运行工具 <code>nmtui</code> 来配置网络接口。</p><p><code>nmtui</code> 是 NetworkManager 工具的一部分，它为你提供了一个友好的用户界面来配置网络。</p><p>这是 <code>NetworkManager-tui</code> 包的一部分，在你完成最小服务器安装后默认安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmtui</span></span></code></pre></div><p>单击 nmtui 窗口中的“<ruby>编辑连接<rt>Edit a connection</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/nmtui-Select-options.jpg" alt="nmtui - 选择选项"></p><p>选择接口名称</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/Select-Interface-to-Edit.jpg" alt="选择要编辑的接口"></p><p>在“<ruby>编辑连接<rt>Edit Connection</rt></ruby>”窗口中，为 IPv4 和 IPv6 选择“<ruby>自动<rt>Automatic</rt></ruby>”选项。并选择“<ruby>自动连接<rt>Automatically Connect</rt></ruby>”。完成后按 “OK”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/nmtui-Edit-Connection.jpg" alt="nmtui - 编辑连接"></p>',13)),a("p",null,[t[6]||(t[6]=e("使用以下命令通过 ",-1)),s(i,{href:"https://www.debugpoint.com/2020/12/systemd-systemctl-service/"},{default:n(()=>[...t[5]||(t[5]=[e("systemd systemctl",-1)])]),_:1}),t[7]||(t[7]=e(" 重启 NetworkManager 服务。",-1))]),t[25]||(t[25]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart NetworkManager</span></span></code></pre></div><p>如果一切顺利，你可以在最小安装的 CentOS、RHEL 和 Rocky Linux 服务器中连接到网络和互联网。前提是你的网络有互联网连接。你可以使用 <code>ping</code> 来验证它是否正常工作。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/setup-internet-minimal-server-CentOS-Rocky-Linux-RHEL.jpg" alt="设置最小化服务器互联网 - CentOS Rocky Linux RHEL"></p><h3 id="附加技巧-在最小化服务器中设置静态-ip" tabindex="-1">附加技巧：在最小化服务器中设置静态 IP <a class="header-anchor" href="#附加技巧-在最小化服务器中设置静态-ip" aria-label="Permalink to “附加技巧：在最小化服务器中设置静态 IP”">​</a></h3><p>当你将网络配置设置为自动时，接口会在你连接到互联网时动态分配 IP。在你设置局域网的某些情况下，你可能希望将静态 IP 分配给你的网络接口。这非常容易。</p><p>打开你的网络配置脚本。将 <code>ens3</code> 改为为你自己的设备名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/sysconfig/network-scripts/ifcfg-ens3</span></span></code></pre></div><p>在上面的文件中，使用 <code>IPADDR</code> 属性添加所需的 IP 地址。保存文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IPADDR=192.168.0.55</span></span></code></pre></div><p>在 <code>/etc/sysconfig/network</code> 中为你的网络添加网关。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NETWORKING=yes</span></span>
<span class="line"><span>HOSTNAME=debugpoint</span></span>
<span class="line"><span>GATEWAY=10.1.1.1</span></span></code></pre></div><p>在 <code>/etc/resolv.conf</code> 中添加任意公共 DNS 服务器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 8.8.8.8</span></span>
<span class="line"><span>nameserver 8.8.4.4</span></span></code></pre></div><p>然后重启网络服务。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart NetworkManager</span></span></code></pre></div><p>这就完成了静态 IP 的设置。你还可以使用 <code>ip addr</code> 命令检查 IP 详细信息。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我希望本指南可以帮助你在最小化安装的服务器中设置网络、互联网和静态 IP。如果你有任何问题，请在评论区告诉我。</p><hr>`,19)),a("p",null,[t[9]||(t[9]=e("via: ",-1)),s(i,{href:"https://www.debugpoint.com/setup-internet-minimal-install-server/"},{default:n(()=>[...t[8]||(t[8]=[e("https://www.debugpoint.com/setup-internet-minimal-install-server/",-1)])]),_:1})]),a("p",null,[t[14]||(t[14]=e("作者：",-1)),s(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...t[10]||(t[10]=[e("Arindam",-1)])]),_:1}),t[15]||(t[15]=e(" 选题：",-1)),s(i,{href:"https://github.com/lkxed"},{default:n(()=>[...t[11]||(t[11]=[e("lkxed",-1)])]),_:1}),t[16]||(t[16]=e(" 译者：",-1)),s(i,{href:"https://github.com/geekpi"},{default:n(()=>[...t[12]||(t[12]=[e("geekpi",-1)])]),_:1}),t[17]||(t[17]=e(" 校对：",-1)),s(i,{href:"https://github.com/wxy"},{default:n(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[20]||(t[20]=e("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原创编译，",-1)),s(i,{href:"https://linux.cn/"},{default:n(()=>[...t[19]||(t[19]=[e("Linux中国",-1)])]),_:1}),t[22]||(t[22]=e(" 荣誉推出",-1))])])}const x=p(u,[["render",g]]);export{C as __pageData,x as default};
